function openDialog(html){$('dialog-content').innerHTML=html;if(!$('car-dialog').open)$('car-dialog').showModal();}
function notice(key){
const notices={
booking:['Plan your booking','Choose a vehicle from our collection, then select Reserve to review your dates and rental estimate.','Browse our fleet'],
contact:['Contact DriveFlex Rentals','Start with your pickup location and travel dates, then choose the vehicle that suits your journey. Our team will confirm availability and collection arrangements.','Explore the fleet'],
help:['How can we help?','Select View Car to compare vehicle specifications, or Reserve to calculate your trip. Rates are in Kenyan shillings and self-drive rentals have a three-day minimum.','Browse cars'],
privacy:['Your privacy','We use your trip details to help prepare your rental. We do not sell your personal information.','Explore the fleet'],
terms:['Rental terms','Daily rates are shown in Kenyan shillings. Availability and final costs depend on the selected vehicle, dates, insurance, deposit, delivery and one-way requirements. Self-drive rentals have a three-day minimum; long-term savings apply to rentals of 30 days or more.','View the fleet'],
app:['Book from any device','Browse the DriveFlex collection, compare specifications and plan your rental from your phone, tablet or computer.','Browse cars']
};const [title,body,cta]=notices[key]||notices.help;
openDialog('<div class="notice"><h2 id="dialog-title">'+title+'</h2><p>'+body+'</p><a class="button" href="fleet.html">'+cta+' →</a></div>');
}
function fleetURL(extra={}){const q=new URLSearchParams({...trip,...extra});return 'fleet.html?'+q.toString();}
function listCars(){const result=cars.filter(c=>category==='All'||c.category===category);const sort=$('sort')?.value;if(sort==='low')result.sort((a,b)=>a.price-b.price);if(sort==='high')result.sort((a,b)=>b.price-a.price);if(sort==='seats')result.sort((a,b)=>b.seats-a.seats);return result;}
function renderFleet(){const list=listCars();$('result-count').textContent=list.length+' vehicles · Kenyan shillings';$('fleet-grid').innerHTML=list.map(c=>'<article class="fleet-card"><div class="fleet-visual"><p class="fleet-category">'+c.category+'</p><img src="'+c.image+'" alt="'+c.name+'" loading="lazy"></div><div class="fleet-info"><h2>'+c.name+' <small>or similar</small></h2><p class="fleet-price">'+money(c.price)+' <small>/ day</small></p>'+specs(c)+'<div class="fleet-actions"><button data-car="'+c.id+'">VIEW CAR</button><button class="reserve" data-reserve="'+c.id+'">RESERVE ❯</button></div></div></article>').join('');}
function showCar(id){const c=cars.find(c=>c.id===id);if(!c)throw Error('Unknown vehicle');openDialog('<img class="dialog-photo" src="'+c.image+'" alt="'+c.name+'"><div class="dialog-body"><p class="fleet-category">'+c.category+'</p><h2 id="dialog-title">'+c.name+'</h2><p class="fleet-price">'+money(c.price)+' <small>/ day</small></p>'+specs(c)+'<p>Comfort, space and flexibility for your next journey.</p><p class="dialog-note">A comparable vehicle may be provided when your selected model is unavailable.</p><button class="button" data-reserve="'+id+'">Reserve this car →</button></div>');}
function reserve(id){const c=cars.find(c=>c.id===id);if(!c)throw Error('Unknown vehicle');openDialog('<div class="dialog-body"><p class="fleet-category">PLAN YOUR RENTAL</p><h2 id="dialog-title">'+c.name+'</h2><p>'+money(c.price)+' per day · 3-day minimum</p><form id="quote-form"><div class="booking-fields"><label>Pick-up Date<input type="date" id="quote-start" required min="'+today+'"></label><label>Drop-off Date<input type="date" id="quote-end" required min="'+today+'"></label><label>Pick-up Time<input type="time" id="quote-start-time" required></label><label>Drop-off Time<input type="time" id="quote-end-time" required></label><label>Pick-up Location<select id="quote-location">'+locations.map(l=>'<option>'+l+'</option>').join('')+'</select></label><label>Drop-off Location<select id="quote-return">'+locations.map(l=>'<option>'+l+'</option>').join('')+'</select></label></div><p class="error" id="quote-error" role="alert"></p><div id="quote-result" aria-live="polite"></div><button class="button" type="submit">Calculate rental estimate →</button><p class="dialog-note">Your selected dates and locations will be used to prepare your booking.</p></form></div>');
$('quote-start').value=trip.start;$('quote-end').value=trip.end;$('quote-start-time').value=trip.startTime;$('quote-end-time').value=trip.endTime;$('quote-location').value=trip.location;$('quote-return').value=trip.returnLocation;
$('quote-form').onsubmit=e=>{e.preventDefault();try{const next={...trip,start:$('quote-start').value,end:$('quote-end').value,startTime:$('quote-start-time').value,endTime:$('quote-end-time').value,location:$('quote-location').value,returnLocation:$('quote-return').value};const q=Rental.estimate({...next,rate:c.price});trip=next;$('quote-error').textContent='';$('quote-result').innerHTML='<div class="estimate"><div>'+q.days+' days × '+money(c.price)+(q.discount?'<small>'+q.percent+'% rental offer (−'+money(q.discount)+')</small>':'')+'<small>Estimated rental total</small></div><strong>'+money(q.total)+'</strong></div><p class="dialog-note">Insurance, deposit, delivery and one-way charges are confirmed with your booking.</p>';}catch(error){$('quote-result').innerHTML='';$('quote-error').textContent=error.message;}};
}
document.addEventListener('click',e=>{const car=e.target.closest('[data-car]'),booking=e.target.closest('[data-reserve]'),info=e.target.closest('[data-info]');if(car)showCar(car.dataset.car);if(booking)reserve(booking.dataset.reserve);if(info){e.preventDefault();notice(info.dataset.info);}});
document.querySelector('.close').onclick=()=>$('car-dialog').close();
